// Transparency-log verification (src/merkle.ts, src/log.ts, verifyReceipt
// opts.inclusion, scripts/verify-log.mjs consistency). Every proof here is
// generated by an independent RECURSIVE reference built straight from the
// RFC 6962 §2.1 definitions (MTH / PATH / SUBPROOF) on node:crypto, so the
// iterative RFC 9162 verifiers in src/ and in scripts/verify-log.mjs are
// each checked against a third implementation, exhaustively for small trees.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createHash, webcrypto } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { canonicalizeBytes } from '../dist/jcs.js';
import {
  verifyReceipt,
  verifyInclusion,
  verifyConsistency,
  parseHash,
  verifySth,
  verifySthConsistency,
  verifyReceiptInclusion,
  receiptLeafHash,
  LogMonitor,
  MemorySthStore,
  checkLogKeyDoc,
  PINNED_KEY_BUNDLE,
  PINNED_LOG_KEYS,
  PINNED_LOG_KEYS_FETCHED_AT,
  LOG_KEYS_URL,
} from '../dist/index.js';
import * as oracle from '../scripts/verify-log.mjs';
import { makeReceipt, makeEphemeralKey, makeKeyBundle, makeRevocations } from './_helpers.mjs';

const subtle = webcrypto.subtle;

// ── Recursive RFC 6962 reference ─────────────────────────────────────────────
const H = (...parts) => { const h = createHash('sha256'); for (const p of parts) h.update(p); return h.digest(); };
const refLeaf = (data) => H(Buffer.from([0]), data);
const refNode = (l, r) => H(Buffer.from([1]), l, r);
const splitK = (n) => { let k = 1; while (k * 2 < n) k *= 2; return k; };
function MTH(D) {
  if (D.length === 0) return H(Buffer.alloc(0));
  if (D.length === 1) return D[0];
  const k = splitK(D.length);
  return refNode(MTH(D.slice(0, k)), MTH(D.slice(k)));
}
function PATH(m, D) {
  if (D.length <= 1) return [];
  const k = splitK(D.length);
  return m < k ? [...PATH(m, D.slice(0, k)), MTH(D.slice(k))]
               : [...PATH(m - k, D.slice(k)), MTH(D.slice(0, k))];
}
function SUBPROOF(m, D, b) {
  if (m === D.length) return b ? [] : [MTH(D)];
  const k = splitK(D.length);
  return m <= k ? [...SUBPROOF(m, D.slice(0, k), b), MTH(D.slice(k))]
                : [...SUBPROOF(m - k, D.slice(k), false), MTH(D.slice(0, k))];
}
const PROOF = (m, D) => SUBPROOF(m, D, true);
const leaves = (n, tag = 'leaf') => Array.from({ length: n }, (_, i) => refLeaf(Buffer.from(`${tag}-${i}`)));
const u8 = (b) => new Uint8Array(b);
const flip = (b, i = 0) => { const c = Buffer.from(b); c[i] ^= 1; return c; };
const hex = (b) => Buffer.from(b).toString('hex');

const MAX = 33;

// ── merkle.ts: inclusion ─────────────────────────────────────────────────────

test('inclusion: every index of every tree up to 33 leaves verifies, and agrees with the CLI oracle', async () => {
  for (let n = 1; n <= MAX; n++) {
    const D = leaves(n);
    const root = MTH(D);
    for (let m = 0; m < n; m++) {
      const path = PATH(m, D);
      const ok = await verifyInclusion({ leafIndex: m, treeSize: n, leaf: u8(D[m]), path: path.map(u8), root: u8(root) });
      assert.equal(ok, true, `n=${n} m=${m}`);
      assert.equal(oracle.verifyInclusion({ leafIndex: m, treeSize: n, leaf: D[m], path, root }), true, `oracle n=${n} m=${m}`);
    }
  }
});

test('inclusion: tampered proofs fail (flipped node, wrong index, wrong size, short/long path, wrong root, wrong leaf)', async () => {
  for (let n = 1; n <= MAX; n++) {
    const D = leaves(n);
    const root = u8(MTH(D));
    for (let m = 0; m < n; m++) {
      const path = PATH(m, D).map(u8);
      const base = { leafIndex: m, treeSize: n, leaf: u8(D[m]), path, root };
      const bad = [];
      if (path.length) {
        for (let j = 0; j < path.length; j++) bad.push({ ...base, path: path.map((p, i) => (i === j ? u8(flip(p)) : p)) });
        bad.push({ ...base, path: path.slice(0, -1) });
      }
      bad.push({ ...base, path: [...path, u8(D[0])] });
      bad.push({ ...base, root: u8(flip(root, 31)) });
      bad.push({ ...base, leaf: u8(flip(D[m])) });
      if (n > 1) bad.push({ ...base, leafIndex: (m + 1) % n });
      bad.push({ ...base, leafIndex: n });
      bad.push({ ...base, leafIndex: -1 });
      bad.push({ ...base, treeSize: 1.5 });
      for (const b of bad) assert.equal(await verifyInclusion(b), false, `n=${n} m=${m}`);
    }
  }
});

test('inclusion: malformed input returns false, never throws', async () => {
  const D = leaves(4);
  const root = u8(MTH(D));
  const path = PATH(1, D).map(u8);
  assert.equal(await verifyInclusion(null), false);
  assert.equal(await verifyInclusion({ leafIndex: 1, treeSize: 4, leaf: u8(D[1]), path: [new Uint8Array(31), ...path.slice(1)], root }), false);
  assert.equal(await verifyInclusion({ leafIndex: 1, treeSize: 4, leaf: u8(D[1]), path: 'nope', root }), false);
  assert.equal(await verifyInclusion({ leafIndex: 1, treeSize: 4, leaf: new Uint8Array(16), path, root }), false);
});

// ── merkle.ts: consistency ───────────────────────────────────────────────────

test('consistency: every m ≤ n up to 33 leaves verifies, and agrees with the CLI oracle', async () => {
  for (let n = 1; n <= MAX; n++) {
    const D = leaves(n);
    const second = MTH(D);
    for (let m = 1; m <= n; m++) {
      const first = MTH(D.slice(0, m));
      const proof = PROOF(m, D);
      const ok = await verifyConsistency({ first: m, second: n, firstRoot: u8(first), secondRoot: u8(second), proof: proof.map(u8) });
      assert.equal(ok, true, `m=${m} n=${n}`);
      assert.equal(oracle.verifyConsistency({ first: m, second: n, firstRoot: first, secondRoot: second, proof }), true, `oracle m=${m} n=${n}`);
    }
  }
});

test('consistency: tampered proofs fail (flipped node, dropped/extra node, swapped or forged roots, wrong sizes)', async () => {
  for (let n = 2; n <= MAX; n++) {
    const D = leaves(n);
    const second = u8(MTH(D));
    for (let m = 1; m < n; m++) {
      const first = u8(MTH(D.slice(0, m)));
      const proof = PROOF(m, D).map(u8);
      const base = { first: m, second: n, firstRoot: first, secondRoot: second, proof };
      const bad = [];
      for (let j = 0; j < proof.length; j++) bad.push({ ...base, proof: proof.map((p, i) => (i === j ? u8(flip(p)) : p)) });
      bad.push({ ...base, proof: proof.slice(0, -1) });
      bad.push({ ...base, proof: [...proof, first] });
      bad.push({ ...base, firstRoot: second, secondRoot: first });
      bad.push({ ...base, firstRoot: u8(flip(first)) });
      bad.push({ ...base, secondRoot: u8(flip(second)) });
      bad.push({ ...base, first: m + 1 === n ? m - 1 || 1 : m + 1 });
      bad.push({ ...base, first: n + 1 });
      // A forked history: a different tree of the same size n that does not
      // contain the first m leaves.
      const F = [...leaves(m, 'fork'), ...D.slice(m)];
      bad.push({ ...base, secondRoot: u8(MTH(F)) });
      for (const b of bad) {
        if (b.first === m && b.second === n && b.firstRoot === first && b.secondRoot === second && b.proof === proof) continue;
        assert.equal(await verifyConsistency(b), false, `m=${m} n=${n}`);
      }
    }
  }
});

test('consistency: equal sizes need equal roots and an empty proof; size 0 needs an empty proof', async () => {
  const D = leaves(5);
  const r = u8(MTH(D));
  assert.equal(await verifyConsistency({ first: 5, second: 5, firstRoot: r, secondRoot: r, proof: [] }), true);
  assert.equal(await verifyConsistency({ first: 5, second: 5, firstRoot: r, secondRoot: u8(flip(r)), proof: [] }), false);
  assert.equal(await verifyConsistency({ first: 5, second: 5, firstRoot: r, secondRoot: r, proof: [r] }), false);
  assert.equal(await verifyConsistency({ first: 0, second: 5, firstRoot: r, secondRoot: r, proof: [] }), true);
  assert.equal(await verifyConsistency({ first: 0, second: 5, firstRoot: r, secondRoot: r, proof: [r] }), false);
  assert.equal(await verifyConsistency({ first: 3, second: 5, firstRoot: r, secondRoot: r, proof: [] }), false);
  assert.equal(await verifyConsistency(null), false);
});

// The RFC 9162 algorithms do not bind the tree size by themselves: a proof
// for size 3 also verifies "for size 4" against the same root. That is why
// log.ts takes every size from the SIGNED tree head and refuses a proof
// whose sizes differ from it. Pinned here so nobody relies on the primitive.
test('raw proofs do not bind tree size; the STH layer must (and does)', async () => {
  const D = leaves(4);
  const r3 = u8(MTH(D.slice(0, 3)));
  const p3 = PATH(0, D.slice(0, 3)).map(u8);
  assert.equal(await verifyInclusion({ leafIndex: 0, treeSize: 4, leaf: u8(D[0]), path: p3, root: r3 }), true);
  assert.equal(await verifyConsistency({ first: 1, second: 4, firstRoot: u8(D[0]), secondRoot: r3, proof: PROOF(1, D.slice(0, 3)).map(u8) }), true);
});

test('parseHash: 32-byte hex only, optional 0x', () => {
  const h = 'ab'.repeat(32);
  assert.ok(parseHash(h));
  assert.ok(parseHash('0x' + h));
  assert.ok(parseHash(h.toUpperCase()));
  for (const bad of ['ab'.repeat(31), 'ab'.repeat(33), 'zz'.repeat(32), h + 'a', '', null, 42, 'ab '.repeat(32)]) {
    assert.equal(parseHash(bad), null, String(bad));
  }
});

// ── STH helpers ──────────────────────────────────────────────────────────────

async function signSth(signer, body, { keyId } = {}) {
  const sig = await subtle.sign('Ed25519', signer.kp.privateKey, canonicalizeBytes(body));
  return {
    ...body,
    signature: {
      algorithm: 'Ed25519',
      ...(keyId ? { key_id: keyId } : {}),
      public_key: signer.publicKeyB64,
      value: Buffer.from(sig).toString('base64'),
    },
  };
}
const logEntry = (signer, key_id, extra = {}) => ({ key_id, algorithm: 'Ed25519', public_key: signer.publicKeyB64, status: 'active', purpose: 'log', ...extra });
const ts = () => new Date().toISOString();

// ── verifySth ────────────────────────────────────────────────────────────────

test('verifySth: pinned log key only; attacker key, unknown key_id, revoked key, missing keys all fail', async () => {
  const log = await makeEphemeralKey();
  const other = await makeEphemeralKey();
  const attacker = await makeEphemeralKey();
  const body = { tree_size: 3, root_hash: 'ab'.repeat(32), timestamp: ts() };
  const keys = [logEntry(log, 'log-1')];

  // Legacy dialect: no key_id, verified against the pinned keys.
  assert.equal((await verifySth(await signSth(log, body), keys)).valid, true);
  assert.equal((await verifySth(await signSth(log, body), keys)).key_id, 'log-1');
  // The STH carries the attacker's public key; it does not matter.
  assert.equal((await verifySth(await signSth(attacker, body), keys)).valid, false);
  // key_id must name a pinned key, and only that key is tried.
  assert.equal((await verifySth(await signSth(log, body, { keyId: 'log-1' }), keys)).valid, true);
  assert.equal((await verifySth(await signSth(log, body, { keyId: 'nope' }), keys)).valid, false);
  const two = [logEntry(other, 'log-2'), logEntry(log, 'log-1')];
  assert.equal((await verifySth(await signSth(log, body, { keyId: 'log-2' }), two)).valid, false);
  // Revoked log key is never used.
  assert.equal((await verifySth(await signSth(log, body), [logEntry(log, 'log-1', { status: 'revoked' })])).valid, false);
  // No pinned log keys: refused, and the error says why.
  const none = await verifySth(await signSth(log, body), undefined);
  assert.equal(none.valid, false);
  assert.match(none.errors.join(';'), /never used for the log/);
  assert.equal((await verifySth(await signSth(log, body), [])).valid, false);
  // requireKeyId refuses a bare STH.
  assert.equal((await verifySth(await signSth(log, body), keys, { requireKeyId: true })).valid, false);
  assert.equal((await verifySth(await signSth(log, body, { keyId: 'log-1' }), keys, { requireKeyId: true })).valid, true);
});

test('verifySth: body tampering, base64url, bad shapes and log_id binding', async () => {
  const log = await makeEphemeralKey();
  const keys = [logEntry(log, 'log-1', { log_id: 'tm-receipts' })];
  const body = { tree_size: 3, root_hash: 'ab'.repeat(32), timestamp: ts(), log_id: 'tm-receipts' };
  const sth = await signSth(log, body);
  assert.equal((await verifySth(sth, keys)).valid, true);
  assert.equal((await verifySth({ ...sth, tree_size: 4 }, keys)).valid, false);
  assert.equal((await verifySth({ ...sth, root_hash: 'cd'.repeat(32) }, keys)).valid, false);
  const toUrl = (s) => s.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  assert.equal((await verifySth({ ...sth, signature: { ...sth.signature, value: toUrl(sth.signature.value) } }, keys)).valid, false);
  assert.equal((await verifySth({ ...sth, signature: { ...sth.signature, algorithm: 'RSA' } }, keys)).valid, false);
  assert.equal((await verifySth(null, keys)).valid, false);
  assert.equal((await verifySth([], keys)).valid, false);
  // The same key pinned for another log does not sign for this one.
  const elsewhere = await signSth(log, { ...body, log_id: 'other-log' });
  assert.equal((await verifySth(elsewhere, keys)).valid, false);
  assert.equal((await verifySth(sth, keys, { logId: 'other-log' })).valid, false);
  // Malformed root / size are errors even when signed.
  assert.equal((await verifySth(await signSth(log, { ...body, root_hash: 'xyz' }), keys)).valid, false);
  assert.equal((await verifySth(await signSth(log, { ...body, tree_size: -1 }), keys)).valid, false);
});

// ── Receipt inclusion ────────────────────────────────────────────────────────

async function receiptInTree(receipt, n, at) {
  const D = leaves(n);
  D[at] = Buffer.from(await receiptLeafHash(receipt));
  return { D, root: MTH(D), path: PATH(at, D) };
}

async function setup() {
  const { receipt, keyId, publicKeyB64 } = await makeReceipt();
  const keys = makeKeyBundle([{ key_id: keyId, algorithm: 'Ed25519', public_key: publicKeyB64, attestation_strength: 'software' }]);
  const log = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const { root, path } = await receiptInTree(receipt, 7, 4);
  const proof = { leaf_index: 4, tree_size: 7, audit_path: path.map(hex), root_hash: hex(root) };
  const sth = await signSth(log, { tree_size: 7, root_hash: hex(root), timestamp: ts() }, { keyId: 'log-1' });
  return { receipt, keys, log, logKeys, proof, sth, revocations: makeRevocations() };
}

test('verifyReceipt: a receipt proven in a 7-leaf log is included', async () => {
  const s = await setup();
  const r = await verifyReceipt(s.receipt, { keys: s.keys, revocations: s.revocations, inclusion: { proof: s.proof, sth: s.sth, logKeys: s.logKeys } });
  assert.equal(r.valid, true, r.errors.join('; '));
  assert.deepEqual(r.log, { status: 'included', tree_size: 7, leaf_index: 4, log_key_id: 'log-1', log_key: 'separate' });
  // STH may ride inside the proof, as /v1/receipts/log/proof serves it.
  const r2 = await verifyReceipt(s.receipt, { keys: s.keys, revocations: s.revocations, inclusion: { proof: { ...s.proof, sth: s.sth }, logKeys: s.logKeys } });
  assert.equal(r2.log.status, 'included', r2.errors.join('; '));
});

test('verifyReceipt: without a proof the log is not_checked; requireInclusion makes that an error', async () => {
  const s = await setup();
  const r = await verifyReceipt(s.receipt, { keys: s.keys, revocations: s.revocations });
  assert.equal(r.valid, true);
  assert.equal(r.log.status, 'not_checked');
  const strict = await verifyReceipt(s.receipt, { keys: s.keys, revocations: s.revocations, requireInclusion: true });
  assert.equal(strict.valid, false);
  assert.match(strict.errors.join(';'), /required but no inclusion proof/);
});

test('verifyReceipt: failed inclusion is an error (other receipt, lying root, wrong size, STH from the receipt key, no log keys)', async () => {
  const s = await setup();
  const base = { keys: s.keys, revocations: s.revocations };
  const expectFailed = async (opts, why) => {
    const r = await verifyReceipt(s.receipt, { ...base, ...opts });
    assert.equal(r.valid, false, why);
    assert.equal(r.log.status, 'failed', why);
    assert.ok(r.errors.some((e) => e.startsWith('log inclusion:')), why);
  };
  // Another receipt's proof.
  const { receipt: other } = await makeReceipt({ payload: { other: true } });
  const o = await receiptInTree(other, 7, 4);
  await expectFailed({ inclusion: { proof: { ...s.proof, audit_path: o.path.map(hex), root_hash: hex(o.root) }, sth: await signSth(s.log, { tree_size: 7, root_hash: hex(o.root), timestamp: ts() }), logKeys: s.logKeys } }, 'other receipt');
  // Proof root disagrees with the signed root.
  await expectFailed({ inclusion: { proof: { ...s.proof, root_hash: 'cd'.repeat(32) }, sth: s.sth, logKeys: s.logKeys } }, 'lying root');
  await expectFailed({ inclusion: { proof: { ...s.proof, tree_size: 8 }, sth: s.sth, logKeys: s.logKeys } }, 'wrong size');
  await expectFailed({ inclusion: { proof: { ...s.proof, leaf_index: 3 }, sth: s.sth, logKeys: s.logKeys } }, 'wrong index');
  // An STH signed by an unpinned key (here: a fresh attacker) fails.
  const attacker = await makeEphemeralKey();
  await expectFailed({ inclusion: { proof: s.proof, sth: await signSth(attacker, { tree_size: 7, root_hash: s.proof.root_hash, timestamp: ts() }), logKeys: s.logKeys } }, 'attacker sth');
  await expectFailed({ inclusion: { proof: s.proof, sth: s.sth, logKeys: [] } }, 'no log keys');
  await expectFailed({ inclusion: { proof: s.proof, logKeys: s.logKeys } }, 'no sth');
  // A tampered receipt (extra field) has a different leaf.
  const r = await verifyReceiptInclusion({ ...s.receipt, extra: 1 }, s.proof, s.sth, s.logKeys);
  assert.equal(r.status, 'failed');
});

// ── STH consistency ──────────────────────────────────────────────────────────

async function history(log, keyId = 'log-1') {
  const D = leaves(20);
  const at = async (n) => signSth(log, { tree_size: n, root_hash: hex(MTH(D.slice(0, n))), timestamp: ts() }, { keyId });
  const proof = (m, n) => ({ first: m, second: n, proof: PROOF(m, D.slice(0, n)).map(hex) });
  return { D, at, proof };
}

test('verifySthConsistency: two pinned STHs and a valid proof pass; roots come from the STHs, never the proof', async () => {
  const log = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const h = await history(log);
  const a = await h.at(6);
  const b = await h.at(13);
  assert.equal((await verifySthConsistency(a, b, h.proof(6, 13), logKeys)).valid, true);
  assert.equal((await verifySthConsistency(a, b, { ...h.proof(6, 13), first_root: a.root_hash, second_root: b.root_hash }, logKeys)).valid, true);

  // The old CLI bug: a proof that is self-consistent for a FORKED history,
  // carrying its own roots. It must not verify against the real STHs.
  const F = [...leaves(13, 'forked')];
  const forged = { first: 6, second: 13, proof: PROOF(6, F).map(hex), first_root: hex(MTH(F.slice(0, 6))), second_root: hex(MTH(F)) };
  assert.equal(await oracle.verifyConsistency({ first: 6, second: 13, firstRoot: Buffer.from(forged.first_root, 'hex'), secondRoot: Buffer.from(forged.second_root, 'hex'), proof: forged.proof.map((x) => Buffer.from(x, 'hex')) }), true, 'the forged proof is internally consistent');
  assert.equal((await verifySthConsistency(a, b, forged, logKeys)).valid, false);
  const { first_root: _f, second_root: _s, ...bareForged } = forged;
  assert.equal((await verifySthConsistency(a, b, bareForged, logKeys)).valid, false);
});

test('verifySthConsistency: rollback, same-size fork, unsigned STH, mismatched sizes all fail', async () => {
  const log = await makeEphemeralKey();
  const attacker = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const h = await history(log);
  const a = await h.at(6);
  const b = await h.at(13);
  assert.equal((await verifySthConsistency(b, a, h.proof(6, 13), logKeys)).valid, false, 'rollback');
  const forkSame = await signSth(log, { tree_size: 6, root_hash: 'ee'.repeat(32), timestamp: ts() }, { keyId: 'log-1' });
  const fork = await verifySthConsistency(a, forkSame, null, logKeys);
  assert.equal(fork.valid, false);
  assert.match(fork.errors.join(';'), /fork/);
  assert.equal((await verifySthConsistency(a, a, null, logKeys)).valid, true, 'same STH is consistent');
  const unsigned = { ...b, signature: { ...b.signature, value: (await signSth(attacker, { tree_size: 13, root_hash: b.root_hash, timestamp: b.timestamp }, { keyId: 'log-1' })).signature.value } };
  assert.equal((await verifySthConsistency(a, unsigned, h.proof(6, 13), logKeys)).valid, false, 'newer not signed by pinned key');
  assert.equal((await verifySthConsistency(a, b, h.proof(5, 13), logKeys)).valid, false, 'proof for other sizes');
  assert.equal((await verifySthConsistency(a, b, { first: 6, second: 13, proof: ['zz'] }, logKeys)).valid, false, 'malformed node');
});

// ── LogMonitor ───────────────────────────────────────────────────────────────

test('LogMonitor: first → unchanged → advanced; a failed advance is not stored', async () => {
  const log = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const h = await history(log);
  const store = new MemorySthStore();
  const mon = new LogMonitor({ logId: 'tm-test', logKeys, store });
  const s4 = await h.at(4);
  const s9 = await h.at(9);
  const s15 = await h.at(15);

  assert.equal((await mon.observe(s4)).status, 'first');
  assert.equal((await mon.observe(s4)).status, 'unchanged');
  let r = await mon.observe(s9);
  assert.equal(r.status, 'unproven');
  assert.equal(r.ok, false);
  assert.equal((await mon.last()).tree_size, 4, 'unproven advance is not stored');
  r = await mon.observe(s9, h.proof(4, 9));
  assert.equal(r.status, 'advanced', r.errors.join('; '));
  assert.equal((await mon.last()).tree_size, 9);
  r = await mon.observe(s15, h.proof(4, 15));
  assert.equal(r.status, 'unproven', 'proof must start at the LAST accepted size');
  assert.equal((await mon.last()).tree_size, 9);
});

test('LogMonitor: fork, rollback and invalid STHs are reported and never replace the last good view', async () => {
  const log = await makeEphemeralKey();
  const attacker = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const h = await history(log);
  const mon = new LogMonitor({ logId: 'tm-test', logKeys });
  await mon.observe(await h.at(8));

  // The log signs a second root for size 8: equivocation.
  const equivocal = await signSth(log, { tree_size: 8, root_hash: 'ee'.repeat(32), timestamp: ts() }, { keyId: 'log-1' });
  const f = await mon.observe(equivocal);
  assert.equal(f.status, 'fork');
  assert.equal(f.ok, false);

  const back = await mon.observe(await h.at(5));
  assert.equal(back.status, 'rollback');

  const forged = await signSth(attacker, { tree_size: 12, root_hash: hex(MTH(h.D.slice(0, 12))), timestamp: ts() }, { keyId: 'log-1' });
  assert.equal((await mon.observe(forged, h.proof(8, 12))).status, 'invalid');

  // A forked history at a larger size with a self-consistent proof of its own.
  const F = [...h.D.slice(0, 3), ...leaves(9, 'fork')];
  const forkedBig = await signSth(log, { tree_size: 12, root_hash: hex(MTH(F)), timestamp: ts() }, { keyId: 'log-1' });
  const bad = await mon.observe(forkedBig, { first: 8, second: 12, proof: PROOF(8, F).map(hex) });
  assert.equal(bad.ok, false);
  assert.equal((await mon.last()).tree_size, 8);
  assert.equal((await mon.last()).root_hash, hex(MTH(h.D.slice(0, 8))));
});

test('LogMonitor: fetchConsistency is used when no proof is passed, and a failed fetch is unproven', async () => {
  const log = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const h = await history(log);
  const calls = [];
  const mon = new LogMonitor({ logId: 'tm-test', logKeys, fetchConsistency: async (m, n) => { calls.push([m, n]); return h.proof(m, n); } });
  await mon.observe(await h.at(3));
  assert.equal((await mon.observe(await h.at(17))).status, 'advanced');
  assert.deepEqual(calls, [[3, 17]]);
  const broken = new LogMonitor({ logId: 'tm-test', logKeys, fetchConsistency: async () => { throw new Error('503'); } });
  await broken.observe(await h.at(3));
  const r = await broken.observe(await h.at(17));
  assert.equal(r.status, 'unproven');
  assert.match(r.errors.join(';'), /503/);
});

test('LogMonitor: a head under a fresh log_id cannot start a new history', async () => {
  // The live log key carries no log_id binding, so the key alone would sign
  // for any log_id. Before the fix logId was optional, and a monitor built
  // without it bucketed by the STH's own log_id, so this head came back
  // 'first'. logId is now required and an STH naming another log is invalid.
  const log = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const mon = new LogMonitor({ logId: 'tm-test', logKeys });
  await mon.observe(await signSth(log, { tree_size: 8, root_hash: 'aa'.repeat(32), timestamp: ts(), log_id: 'tm-test' }, { keyId: 'log-1' }));
  const elsewhere = await signSth(log, { tree_size: 2, root_hash: 'ee'.repeat(32), timestamp: ts(), log_id: 'tm-test-2' }, { keyId: 'log-1' });
  const r = await mon.observe(elsewhere);
  assert.equal(r.status, 'invalid', r.errors.join('; '));
  assert.equal((await mon.last()).tree_size, 8);
  assert.throws(() => new LogMonitor({ logKeys }), /logId is required/);
});

test('LogMonitor: concurrent observe() calls are serialized and never roll the view back', async () => {
  const log = await makeEphemeralKey();
  const logKeys = [logEntry(log, 'log-1')];
  const h = await history(log);
  const mon = new LogMonitor({ logId: 'tm-test', logKeys });
  await mon.observe(await h.at(4));
  // Both proofs start at 4. Serialized, the first advances to 9 and the
  // second (4→15) no longer starts at the last accepted size.
  const [a, b] = await Promise.all([
    mon.observe(await h.at(9), h.proof(4, 9)),
    mon.observe(await h.at(15), h.proof(4, 15)),
  ]);
  assert.equal(a.status, 'advanced');
  assert.equal(b.status, 'unproven');
  assert.equal((await mon.last()).tree_size, 9);
  // In the other order the larger head wins and the smaller is a rollback.
  const mon2 = new LogMonitor({ logId: 'tm-test', logKeys });
  await mon2.observe(await h.at(4));
  const [c, d] = await Promise.all([
    mon2.observe(await h.at(15), h.proof(4, 15)),
    mon2.observe(await h.at(9), h.proof(4, 9)),
  ]);
  assert.equal(c.status, 'advanced');
  assert.equal(d.status, 'rollback');
  assert.equal((await mon2.last()).tree_size, 15);
});

test('verifySth: a log key past rotation_after, before created_at, or windowed with no timestamp fails', async () => {
  const log = await makeEphemeralKey();
  const body = { tree_size: 3, root_hash: 'ab'.repeat(32), timestamp: '2026-11-07T12:00:00.000Z' };
  const sth = await signSth(log, body, { keyId: 'log-1' });
  const inWindow = [logEntry(log, 'log-1', { created_at: '2026-05-01T00:00:00Z', rotation_after: '2027-05-01T00:00:00Z' })];
  assert.equal((await verifySth(sth, inWindow)).valid, true);
  const retired = await verifySth(sth, [logEntry(log, 'log-1', { status: 'rotated', rotation_after: '2026-11-01T00:00:00Z' })]);
  assert.equal(retired.valid, false);
  assert.match(retired.errors.join(';'), /sth timestamp is after key log-1 rotation_after/);
  assert.equal((await verifySth(sth, [logEntry(log, 'log-1', { created_at: '2026-12-01T00:00:00Z' })])).valid, false);
  const { timestamp: _t, ...noTs } = body;
  const bare = await verifySth(await signSth(log, noTs, { keyId: 'log-1' }), inWindow);
  assert.equal(bare.valid, false);
  assert.match(bare.errors.join(';'), /no valid timestamp/);
  // A key with no window still verifies a head with no timestamp.
  assert.equal((await verifySth(await signSth(log, noTs, { keyId: 'log-1' }), [logEntry(log, 'log-1')])).valid, true);
});

